import sys
from collections import defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    n = int(sys.stdin.readline())
    adj = defaultdict(list)
    edge_char = {}
    for i in range(2, n+1):
        p, c = sys.stdin.readline().split()
        p = int(p)
        adj[p].append(i)
        adj[i].append(p)
        edge_char[(p, i)] = c
        edge_char[(i, p)] = c

    res = [0] * (n + 1)

    def dfs(u, parent):
        max_len = 0
        char_counts = defaultdict(int)
        for v in adj[u]:
            if v != parent:
                child_max, child_counts = dfs(v, u)
                max_len = max(max_len, child_max)
                for c, cnt in child_counts.items():
                    char_counts[c] += cnt
        char_counts[edge_char[(u, parent)] if parent != 0 else ''] += 1
        odd = 0
        for cnt in char_counts.values():
            if cnt % 2 != 0:
                odd += 1
        if odd <= 1:
            max_len += 1
        else:
            max_len = 0
        res[u] = max_len
        return max_len, char_counts

    dfs(1, 0)
    for i in range(1, n+1):
        print(res[i], end=' ')

